import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;class Solution{static List<Path> files(Path root)throws IOException{try(var stream=Files.walk(root)){return stream.filter(Files::isRegularFile).sorted().toList();}}static void save(Path path,List<String> values)throws IOException{Path temp=path.resolveSibling(path.getFileName()+".tmp");Files.write(temp,values,StandardCharsets.UTF_8);try{Files.move(temp,path,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException error){Files.move(temp,path,StandardCopyOption.REPLACE_EXISTING);}}}
